    "An existing private GitHub repository, in owner/repo form.": "既存の非公開 GitHub リポジトリを owner/repo の形式で指定します。",
    "Empty uses the repository's default branch. Empty repositories are initialized by the first sync; other branches must already exist.": "空欄ならリポジトリのデフォルトブランチを使います。空のリポジトリは最初の同期で初期化されます。その他のブランチは既存のものを指定してください。",
    "The GitHub repository is empty: leave Branch empty or use its default branch for the first sync": "GitHub リポジトリが空です。最初の同期ではブランチを空欄にするか、デフォルトブランチを指定してください",
    "The encrypted backup goes in <folder>/magpie/magpie.magpie-backup. Each update creates a commit.": "暗号化したバックアップは <folder>/magpie/magpie.magpie-backup に保存します。更新ごとにコミットを作成します。",
    "A fine-grained token for this repository with Contents: read and write. Kept on this computer, separately from the library's GitHub token.": "このリポジトリの Contents 読み書き権限を持つ細粒度トークン。本機に保存し、ライブラリの GitHub トークンとは別に管理します。",
    "Name the GitHub repository as owner/repo": "GitHub リポジトリを owner/repo の形式で入力してください",
