    "Model name in replies": "応答のモデル名",
    "What a reply's model says when the request went out under another name than the agent asked for. The X-Magpie-Model header names the member to every agent, and a request's X-Magpie-Response-Model (asked, member or vendor) picks for itself": "エージェントが求めた名前とは別の名前でリクエストが送られたとき、応答の model に何を記すか。X-Magpie-Model ヘッダーはどのエージェントにも答えたメンバーを記し、リクエストの X-Magpie-Response-Model（asked、member、vendor）はそのリクエストだけを決めます",
    "The model asked for": "求めたモデル",
    "The group, alias or provider/model the agent asked for. A reply the vendor named as asked keeps the vendor's name": "エージェントが求めたルーティンググループ、エイリアス、provider/model。ベンダーが求めた名前のまま答えた応答はベンダーの名前のまま",
    "The member that answered": "答えたメンバー",
    "magpie's provider/model that answered (workbuddy/glm-5.3-flash), for every agent, groups included": "答えた magpie の provider/model（workbuddy/glm-5.3-flash）。どのエージェントにも、ルーティンググループでも",
