    "Claude Code isn't installed on this computer": "このコンピュータには Claude Code がインストールされていません",
    "A Claude subscription runs Claude Code as a person does, in its interactive mode, where the plan counts a request at about half of what -p uses. On, no request ever runs as -p. Off runs every request as claude -p": "Claude サブスクリプションは人と同じように Claude Code を対話モードで実行し、プランはリクエストを -p の約半分として数えます。オンのときは、どのリクエストも -p では実行しません。オフにするとすべてのリクエストを claude -p で実行します",
    "Claude requests fail: {why}": "Claude へのリクエストはエラーになります：{why}",
    "A Claude subscription answers with the agent's own instructions as its system prompt, in place of Claude Code's, about 1K fewer tokens each request. Still the real Claude Code, but its requests look less like Claude Code's own, which can put the account more at risk": "Claude サブスクリプションは Claude Code のものの代わりにエージェント自身の指示をシステムプロンプトとして応答し、リクエストごとに約 1K トークン少なくなります。本物の Claude Code のままですが、リクエストが Claude Code 自身のものらしくなくなるため、アカウントのリスクが高まる可能性があります",
    "Ask again after a refusal": "拒否のあと聞き直す",
    "When a vendor's safety filter refuses a request before anything is said, how many more accounts or routing group members are asked. Never ask again hands the refusal straight back: Claude Code then switches to its own fallback model, as it does on Anthropic's API": "ベンダーの安全フィルターが何も言わないうちにリクエストを拒否したとき、ほかのアカウントやルーティンググループのメンバーにあと何回聞くか。「聞き直さない」は拒否をそのまま返します。Claude Code は Anthropic の API のときと同じく、自分のフォールバックモデルに切り替えます",
    "Never ask again": "聞き直さない",
    "Disabled models": "無効にしたモデル",
    "Disable a model": "モデルを無効にする",
    "A disabled model is refused on every route through magpie (a request, a session, a routing group, a fallback, a sub-agent, a decision model) and left out of magpie's lists and agents' pickers. Only requests through magpie are covered. Type a pattern such as *fable* to disable every model it matches": "無効にしたモデルは magpie を通るすべての経路（直接のリクエスト、セッション、ルーティンググループ、フォールバック、サブエージェント、判定モデル）で拒否され、magpie の一覧やエージェントのモデル選択にも出ません。対象は magpie を通るリクエストだけです。*fable* のようなパターンを入力すると、一致するすべてのモデルを無効にできます",
    "Disable…": "無効にする…",
