    "This key is told the quotas of the providers whose every model it may use, and of the accounts it may use, account names included. Click to stop.": "このキーには、すべてのモデルを使えるプロバイダーと、使えるアカウントの残量が、アカウント名も含めて見えます。クリックで止めます。",
    "A key held to a budget, models or accounts is told no quotas. Click to tell it the quotas of the providers whose every model it may use, and of the accounts it may use, account names included.": "予算・モデル・アカウントを限定したキーには残量が見えません。クリックすると、すべてのモデルを使えるプロバイダーと、使えるアカウントの残量が、アカウント名も含めて見えるようになります。",
