    "Estimated cost limit, US$": "推定費用の上限（米ドル）",
    "Estimated cost, US$": "推定費用（米ドル）",
    "Count cache reads too": "キャッシュ読み取りも数える",
    "Tokens are each call's uncached input, output and cache writes. The cost is an estimate at the Usage page's prices, not a bill. Windows are calendar ones in this computer's time (a week from Monday), or every N days or N hours from when the limit is set or reset. Requests from this computer without a key aren't limited.": "トークンは各呼び出しのキャッシュされない入力、出力、キャッシュ書き込みの合計です。費用は使用量ページの価格による推定で、請求額ではありません。期間はこのコンピュータの時刻によるカレンダー単位（週は月曜日から）か、上限を設定またはリセットした時から N 日ごとか N 時間ごとです。このコンピュータからのキーなしのリクエストは制限されません。",
    "Tokens is a count, like 2000000 or 2M": "トークンは数で指定します（例：2000000 や 2M）",
    "The cost is US dollars, like 5 or 2.50": "費用は米ドルで指定します（例：5 や 2.50）",
