    "The tokens and cost {name} has used go back to 0 together. Calls so far in this window stop counting; it still resets {when}.": "{name} が使ったトークンと費用を一緒に 0 に戻します。この期間のこれまでの呼び出しは数えなくなり、リセットは引き続き {when} です。",
