    "Key holders see their usage and setup at": "キーの持ち主はここで自分の使用量と設定方法を確認できます：",
    "Key page": "キーのページ",
    "Gateway keys are for other computers, and for a tunnel to this one such as Cloudflare Tunnel: they are added here once Share on local network is on. Agents on this computer need none.": "ゲートウェイキーは他のコンピュータや、Cloudflare Tunnel などこのコンピュータへのトンネル用です。「ローカルネットワークで共有」をオンにするとここで追加できます。このコンピュータのエージェントには不要です。",
    "Gateway key name": "ゲートウェイキー名",
