    "Create": "作成",
    "Your own key (optional)": "独自のキー（任意）",
    "Gateway key value": "ゲートウェイキーの値",
    "Leave empty and magpie makes a key. Or enter one your clients already send, from another gateway, so they keep working.": "空欄なら magpie がキーを作成します。他のゲートウェイから移行する場合など、クライアントが既に送っているキーを入力すると、クライアントはそのまま使えます。",
    "Gateway key created. Clients that send this key reach magpie now.": "ゲートウェイキーを作成しました。このキーを送るクライアントはそのまま magpie に接続できます。",
    "Use a key between 8 and 256 characters": "キーは 8〜256 文字にしてください",
    "A key can have only letters, digits and ASCII symbols, no spaces": "キーに使えるのは英数字と ASCII 記号だけで、空白は使えません",
    "A key of your own can't start with sk-magpie-: leave the key empty and magpie makes one": "独自のキーは sk-magpie- で始められません。空欄にすると magpie が作成します",
    "Another gateway key already has this key": "このキーは別のゲートウェイキーで使われています",
    "Gateway key created. Use Copy on its row to connect a client.": "ゲートウェイキーを作成しました。行のコピーを使ってクライアントを接続してください。",
