    "subagent effort": "サブエージェントの推論レベル",
    "memories": "メモリ整理のモデル",
    "Codex's own: gpt-5.6-terra/luna, or the session's magpie model": "Codex の初期設定（gpt-5.6-terra/luna）、またはセッションの magpie モデル",
    "opus effort": "opus の推論レベル",
    "sonnet effort": "sonnet の推論レベル",
