    "Same as the lead": "リードと同じ",
    "The lead picks each subagent's model; one it names none for runs on the lead's model ({model}). A resumed subagent stays on the model it started on. A model picked here holds every subagent to it, even when the lead names another.": "各サブエージェントのモデルはリードが選びます。指定がなければリードのモデル（{model}）で動きます。再開したサブエージェントは最初のモデルのままです。ここでモデルを選ぶと、リードが別のモデルを指定しても、すべてのサブエージェントがそのモデルに固定されます。",
    "The lead picks each subagent's model; one it names none for runs on the lead's model. A resumed subagent stays on the model it started on. A model picked here holds every subagent to it, even when the lead names another.": "各サブエージェントのモデルはリードが選びます。指定がなければリードのモデルで動きます。再開したサブエージェントは最初のモデルのままです。ここでモデルを選ぶと、リードが別のモデルを指定しても、すべてのサブエージェントがそのモデルに固定されます。",
    "Every subagent runs on this model, even when the lead names another. Same as the lead gives the pick back to the lead.": "リードが別のモデルを指定しても、すべてのサブエージェントがこのモデルで動きます。「リードと同じ」を選ぶと、選択をリードに戻します。",
    "Codex's config still starts subagents on {model} when the lead names none; picking here replaces it.": "Codex の設定には、リードが指定しないときのサブエージェントのモデルとして {model} が残っています。ここで選ぶとそれを置き換えます。",
    "{model}, or another the lead picks for a subagent": "{model}、またはリードがサブエージェントに選ぶ別のモデル",
    "the lead's model, or another the lead picks for a subagent": "リードと同じモデル、またはリードがサブエージェントに選ぶ別のモデル",
    "Codex subagent model": "Codex サブエージェントのモデル",
    "{agent} settings": "{agent} の設定",
    "In {agent}'s settings, on the Agents page": "エージェントページの {agent} の設定にあります",
    "no title, nothing sent": "タイトルなし、送信なし",
    "no description, nothing sent": "説明なし、送信なし",
    "A GPT lead spawns subagents on magpie’s other models. New threads only; Codex’s own multi_agent_v2 still wins": "GPT のリードが magpie の他のモデルでサブエージェントを起動します。新しいスレッドのみ。Codex 自身の multi_agent_v2 が優先されます",
    "Codex's own multi_agent_v2 is on in the config magpie routes, which takes over the multi-agent V1 magpie's models ask for; turn it off in Codex's config to run subagents on magpie's models.": "magpie が中継する設定で Codex 自身の multi_agent_v2 がオンになっており、magpie のモデルが必要とする multi-agent V1 を上書きします。magpie のモデルでサブエージェントを動かすには、Codex の設定でオフにしてください。",
    "Codex's multi-agent V1 is on, but magpie couldn't read Codex's config to check its own multi_agent_v2.": "Codex の multi-agent V1 はオンですが、magpie は Codex の設定を読めなかったため、それ自身の multi_agent_v2 を確認できません。",
