    "A computer asleep then sends it on waking, up to an hour late; later than that, the day is left be.": "その時刻にコンピュータがスリープしていた場合は、復帰後 1 時間以内なら送信します。それより遅ければその日はスキップします。",
    "Nothing is sent while the computer sleeps: a window that resets then starts when it wakes, and counts from then.": "コンピュータのスリープ中は送信しません。スリープ中にリセットされた期間は復帰時に開始され、そこから数えます。",
    "With Weekly and 5-hour on, a window that would still be running then isn't started on its reset: the windows follow one another from this time.": "「週と 5 時間」がオンのときは、その時刻にまだ動いている枠はリセット時に開始されません。枠はこの時刻から順に続きます。",
