    "On, on the CPU: CoreML failed ({error})": "オン、CPU で実行中：CoreML が失敗しました（{error}）",
    "On: the model starts with the next request": "オン：次のリクエストでモデルが起動します",
    "Off. The model is downloaded ({size})": "オフ。モデルはダウンロード済み（{size}）",
    "Your own words to keep from vendors, separated by commas": "ベンダーに見せたくない語（カンマ区切り）",
    "names, codenames, hosts": "人名、コードネーム、ホスト名",
    "Masking rules": "マスクルール",
    "Secrets magpie doesn't know, such as a gateway's own keys: what they start with, or a regular expression. Masked while Mask secrets is on": "magpie が認識しないシークレット（独自ゲートウェイのキーなど）を、先頭の文字列または正規表現で指定します。「シークレットをマスク」がオンのときにマスクされます",
