    "Regex": "正規表現",
    "Starts with {p}": "{p} で始まる",
    "Matches {re}": "{re} に一致",
    "that masking rule is no longer there: it was changed or removed meanwhile": "そのマスキングルールはもうありません：その間に変更または削除されました",
    "a masking rule needs a prefix or a regular expression": "マスキングルールにはプレフィックスか正規表現が必要です",
    "Web search": "ウェブ検索",
    "Search APIs": "検索 API",
    "Search API": "検索 API",
    "When a model can't search the web, magpie searches for it with these, in this order, and gives it what they found": "モデルがウェブ検索できないとき、magpie がこれらを上から順に使って代わりに検索し、結果をモデルに渡します",
    "Now done by {who}; these come after it": "現在は {who} が検索しています。これらはその後に使われます",
    "Asked before {who}, which searches when these fail": "まずこれらで検索し、すべて失敗したときに {who} が検索します",
    "Search first with": "優先して使う検索",
    "MCP server": "MCP サーバー",
    "Cursor, Claude Desktop and other agents can add this search as an MCP server (Streamable HTTP), with a web_search tool and a web_fetch tool that reads a page by its URL. From another computer, send a gateway key as Authorization: Bearer <key>.": "Cursor、Claude Desktop などのエージェントは、この検索を MCP サーバー（Streamable HTTP）として追加できます。web_search ツールと、URL でページを読む web_fetch ツールがあります。別のコンピューターからは、ゲートウェイキーを Authorization: Bearer <key> として送ってください。",
    "Ask {name}": "{name} を使う",
    "Off: kept with its key, and never asked": "オフ：キーごと残し、呼び出さない",
    "On: asked in its turn": "オン：順番が来たら呼び出す",
    "Image recognition MCP server": "画像認識 MCP サーバー",
    "Agents can add image recognition as an MCP server (Streamable HTTP) with one analyze_image tool, which reads an image with the Image recognition model from a file path, a URL or a data URL. From another computer, send a gateway key as Authorization: Bearer <key> and the image as a URL or data URL.": "エージェントは、画像認識を analyze_image ツール 1 つを持つ MCP サーバー（Streamable HTTP）として追加できます。画像認識のモデルで、ファイルパス、URL、data URL の画像を読み取ります。別のコンピューターからは、ゲートウェイキーを Authorization: Bearer <key> として送り、画像は URL か data URL で渡してください。",
    "The other is asked when it fails": "失敗したときはもう一方を使います",
    "Models that search by themselves": "自分でウェブ検索するモデル",
    "Search with their provider's own search, or with magpie's, as every other model does": "プロバイダのネイティブなウェブ検索を使うか、ほかのモデルと同じく magpie の検索を使います",
    "Their own": "ネイティブ検索",
    "magpie has nothing to search with: add a Search API above, or pick a provider under Searches for other models": "magpie が検索に使えるものがありません。上で検索 API を追加するか、「他のモデルの代わりに検索」でプロバイダを選んでください",
    "magpie's": "magpie の検索",
    "When provider search is off, only configured Search APIs are used, for every model. Without a Search API, magpie does not add a search tool.": "プロバイダによる代行検索がオフの場合、どのモデルにも設定済みの検索 API のみを使用します。検索 API がない場合、magpie は検索ツールを追加しません。",
    "Model search": "モデルによる代理検索",
    "No provider can search, so these are asked": "検索できるプロバイダがないため、これらを使います",
    "When provider search is off, only configured Search APIs are used. Without a Search API, magpie does not add a search tool. Providers' native web search is unchanged.": "プロバイダによる代行検索がオフの場合、設定済みの検索 API のみを使用します。検索 API がない場合、magpie は検索ツールを追加しません。プロバイダのネイティブなウェブ検索には影響しません。",
    "Provider search is off; only these APIs are used": "プロバイダによる代行検索はオフです。これらの API のみを使用します",
    "Searches for other models": "他のモデルの代わりに検索",
    "When a model can't search the web directly, the selected provider searches for it and returns the results. Searches may use the service's quota or incur charges; if the provider magpie picks fails, it tries other available sources, and a provider you select here gives way to the ones you add after it, in their order, then, when it can't search at all (out of quota or rate-limited), to other available sources, then to your Search APIs.": "モデルが直接ウェブ検索できない場合、選択したプロバイダが代わりに検索し、結果を返します。検索にはサービスの利用枠を消費したり、料金が発生したりする場合があります。magpie が自動で選んだプロバイダが失敗すると他の利用可能な検索元を試しますが、ここで選んだプロバイダが失敗すると、その後ろに追加したプロバイダをその順番で試し、利用枠切れやレート制限でまったく検索できないときは他の利用可能な検索元も試し、最後に設定済みの検索 API を使います。",
    "{who} didn't search {when}: {why}. {next} searched in its place.": "{who} は{when}、検索できませんでした：{why}。代わりに {next} が検索しました。",
    "{who} didn't search {when}: {why}. The ones after it didn't search either; add another provider after it, or a Search API.": "{who} は{when}、検索できませんでした：{why}。後ろのプロバイダも検索できませんでした。後ろに別のプロバイダを追加するか、検索 API を追加してください。",
    "If it fails": "失敗したとき",
    "These providers search in its place, in this order, when the one above fails; no other provider does.": "上のプロバイダが検索に失敗すると、これらのプロバイダがこの順番で代わりに検索します。他のプロバイダは使われません。",
    "{who} didn't search {when}: {why}. No other provider searched in its place; pick Automatic or another provider, or add a Search API.": "{who} は{when}、検索できませんでした：{why}。他のプロバイダが代わりに検索することはありません。「自動」か別のプロバイダを選ぶか、検索 API を追加してください。",
    "it answered without searching the web, so its account or plan may not offer web search": "ウェブ検索をせずに回答しました。アカウントやプランがウェブ検索に対応していない可能性があります",
    "no provider that searches": "検索できるプロバイダなし",
    "{model}, its small model": "{model}（その小型モデル）",
    "its web search": "そのウェブ検索",
    "A Kimi Code plan ({names}) searches for its own models first, with its web search; for other models only when named here": "Kimi Code プラン（{names}）は自身のモデルについてはまず自身のウェブ検索を使います。他のモデルには、ここで選んだ場合のみ使います",
    "{names} search for their own models first, with Gemini's Google Search": "{names} は自身のモデルについてはまず Gemini の Google 検索を使います",
    "it is no longer in magpie": "magpie にもう存在しません",
    "it is turned off": "オフになっています",
