    "These relays must be selected manually and are not used for automatic selection or fallback: {names}.": "次の中継サービスは手動で選択する必要があり、自動選択や自動フォールバックの対象にはなりません：{names}。",
    "These providers can't be selected to search for other models with the current configuration: {names}. Their models can still get search results through other available search providers or configured search APIs.": "次のプロバイダは現在の設定では他のモデルの検索用に選択できません：{names}。これらのモデルも、他の利用可能な検索用プロバイダや設定済みの検索 API を通じて検索結果を取得できます。",
    "{names} and {n} more": "{names} ほか {n} 件",
