    "magpie forgets its copy of {users}. {agent}'s own files and sign-in, and the account itself, are left as they are.": "magpie は保存している {users} のコピーを削除します。{agent} 自身のファイルとサインイン、アカウント自体はそのままです。",
    "signed in": "サインイン済み",
