    "magpie left it unchanged and lists no providers from it. Fix the file or move it aside, then reopen this page; until then, changes to providers are refused.": "magpie はファイルを変更せず、そこからプロバイダを一覧表示しません。ファイルを修正するか別の場所に移してから、このページを開き直してください。それまでプロバイダの変更は拒否されます。",
