    "GitHub token": "GitHub トークン",
    "Create one ↗": "作成 ↗",
    "The library checks skills for updates with it: GitHub allows 5,000 requests an hour with a token, 60 without. It also installs skills from private repositories it can read; for public ones it needs no scopes.": "ライブラリはこれを使ってスキルのアップデートを確認します。GitHub はトークンありで1時間に5,000リクエスト、なしでは60リクエストまで許可します。読み取れるプライベートリポジトリからのスキルのインストールにも使います。公開リポジトリならスコープは不要です。",
    "Using {env} from the environment ({mask}); a token set here comes first.": "環境変数の {env} を使用中（{mask}）。ここで設定したトークンが優先されます。",
    "a GitHub token is one word, without spaces": "GitHub トークンはスペースを含まない1つの文字列です",
    "GitHub's rate limit for your GitHub token is used up until {time}": "GitHub トークンのレート制限は {time} まで使い切られています",
    "GitHub's rate limit for your GitHub token is used up for now": "GitHub トークンのレート制限は現在使い切られています",
    "GitHub allows 60 requests an hour without a token, used up until {time}. Add a GitHub token in Settings → Network and sharing to raise it to 5,000.": "GitHub はトークンなしでは1時間に60リクエストまで許可しており、{time} まで使い切られています。設定 → ネットワークと共有 で GitHub トークンを追加すると5,000に増えます。",
    "GitHub allows 60 requests an hour without a token, used up for now. Add a GitHub token in Settings → Network and sharing to raise it to 5,000.": "GitHub はトークンなしでは1時間に60リクエストまで許可しており、現在使い切られています。設定 → ネットワークと共有 で GitHub トークンを追加すると5,000に増えます。",
    "GitHub refused the GitHub token in Settings → Network and sharing: it may have expired or been revoked": "GitHub が 設定 → ネットワークと共有 の GitHub トークンを拒否しました。期限切れか取り消された可能性があります",
