    "from a link": "リンクから",
    "Fetching {host}’s icon…": "{host} のアイコンを取得中…",
    "the vendor": "ベンダー",
    "This link can't be imported: {e}": "このリンクはインポートできません：{e}",
    "Added from a link. Your prompts and this key will go to {hosts}; add it only if you trust the site that sent you here.": "リンクから追加されました。プロンプトとこのキーは {hosts} に送られます。このページへ案内したサイトを信頼できる場合のみ追加してください。",
    "From the link. Kept in ~/.config/magpie/providers.json, readable by you alone.": "リンクから。~/.config/magpie/providers.json に保存され、あなただけが読めます。",
    "Replaces your {name}, key and all.": "既存の {name} をキーも含めて置き換えます。",
