    "API key": "APIキー",
    "Kept in ~/.config/magpie/providers.json, readable by you alone. Nothing is read from your shell.": "~/.config/magpie/providers.json に保存され、あなただけが読めます。シェルからは何も読み込みません。",
    "model ids, comma separated · e.g. gpt-5.5, claude-sonnet-5": "モデル ID、カンマ区切り · 例：gpt-5.5, claude-sonnet-5",
    "Optional: Fetch models to pick from the vendor's list, or type ids; none picked, magpie asks for the list after saving.": "任意：「モデルを取得」でベンダーの一覧から選ぶか、ID を入力します。何も選ばなければ、保存後に magpie が一覧を取得します。",
    "Fetch models": "モデルを取得",
    "Ask the vendor for its model list with the URL and key typed, to pick from; nothing is saved": "入力した URL とキーでベンダーにモデル一覧を問い合わせて選択します。何も保存されません",
    "Asking the vendor…": "ベンダーに問い合わせ中…",
    "The vendor's list is empty. Type the model ids instead.": "ベンダーの一覧が空です。モデル ID を入力してください。",
