    "Two plugins sign in to {name}; magpie runs it on one. Use for {name} on the other one's row switches it": "2 つのプラグインが {name} にサインインします。magpie が使うのは 1 つだけです。もう一方の行の「{name} に使う」で切り替えられます",
    "Two plugins sign in to {name}; magpie runs it on one. Use for {name} switches it to this one, or remove the one you don't want": "2 つのプラグインが {name} にサインインします。magpie が使うのは 1 つだけです。「{name} に使う」でこのプラグインに切り替えるか、不要な方を削除してください",
