    "An OpenCode provider plugin — its npm package or a path. Plugins are other people's code: they sign in and make the requests.": "OpenCode のプロバイダプラグインです。npm パッケージ名またはパスを入力します。プラグインは他者のコードで、サインインとリクエストを行います。",
