    "Syncing here now. The {other} settings are kept, not synced to: pick {other} to see them.": "現在ここに同期しています。{other} の設定は保持されていますが同期されません。{other} を選ぶと表示されます。",
    "{active} is synced to now. Saving moves sync here; the {active} settings are kept for moving back.": "現在は {active} に同期しています。保存すると同期先がここに移ります。{active} の設定は戻すときのために保持されます。",
