    "Empty for AWS S3; for R2, B2, MinIO and the like, their S3 API address.": "AWS S3 は空欄。R2、B2、MinIO などはその S3 API のアドレスを入力します。",
    "The backup goes in a folder named magpie under it.": "バックアップはその中の magpie という名前のフォルダーに保存されます。",
