    "Versions": "バージョン",
    "Versions kept": "残す数",
    "What is here now is backed up first: restore that one to undo this.": "いまの設定を先にバックアップします。それを復元すれば元に戻せます。",
    "What was here before a restore": "復元前の設定",
    "What was here before is the version of {when}: restore it to undo.": "復元前の設定は {when} のバージョンとして残っています。それを復元すれば元に戻せます。",
    "Your providers, settings and profiles, without API keys or sign-ins, into a folder on this computer": "プロバイダ、設定、プロファイルを（API キーとサインインを除いて）このコンピュータのフォルダへ",
    "Your providers, settings, profiles and agents' models become this backup's. Providers added since are kept, and each keeps its API keys here.": "プロバイダ、設定、プロファイル、各エージェントのモデルがこのバックアップのものになります。その後に追加したプロバイダは残り、各プロバイダのこのコンピュータの API キーもそのままです。",
