    "the server answered with an XML document instead of the file: check the address is the server's WebDAV address": "サーバーがファイルではなく XML 文書を返しました：アドレスがサーバーの WebDAV アドレスか確認してください",
    "the file on the server is another app's (“{format}”), not a magpie backup": "サーバー上のファイルは別のアプリのもの（「{format}」）で、magpie のバックアップではありません",
    "the file on the server is a JSON file that isn't a magpie backup ({size})": "サーバー上のファイルは magpie のバックアップではない JSON ファイルです（{size}）",
    "the file on the server isn't a magpie backup: it is {type} ({size})": "サーバー上のファイルは magpie のバックアップではありません：{type}（{size}）です",
    "Upload this computer's setup": "このコンピューターの設定をアップロード",
    "It replaces the file on the server. That file is kept in the sync folder first.": "サーバー上のファイルを置き換えます。そのファイルは先に同期フォルダーに保存されます。",
    "Upload…": "アップロード…",
    "Replace the file on the server?": "サーバー上のファイルを置き換えますか？",
