    "Providers with the same id are replaced; one that came without a key keeps the key it has here. The library replaces the one here, which is kept with its backups.": "同じ ID のプロバイダは置き換えられます。キーなしで来たものはここにあるキーを保持します。ライブラリはここのものを置き換え、置き換えられたものはバックアップとともに保持されます。",
