    "Model ids without the provider": "プロバイダなしのモデル ID",
    "The gateway’s model list also names each model by its own id, as gpt-5.6-sol beside codex/gpt-5.6-sol, for apps moved from another proxy. One that several providers serve goes to them in the Providers order": "ゲートウェイのモデル一覧に、各モデルを自身の ID でも載せます（codex/gpt-5.6-sol の隣に gpt-5.6-sol）。ほかのプロキシから移ってきたアプリ向けです。複数のプロバイダが提供するモデルは「プロバイダ」の順に送られます",
    "Busy models last": "混雑しているモデルを後回しに",
    "A model its plugin says is busier than this goes after the others a request could go to, as its vendor makes it wait. One with no load reported in the last 5 minutes keeps its place": "プラグインがこの値より混雑していると報告したモデルは、リクエストの送り先になるほかのモデルの後に回します。ベンダーの順番待ちになるためです。直近 5 分間に負荷の報告がないモデルは元の位置のままです",
    "Over {n}%": "{n}% 超",
    "A load is in percent, as the plugin reports it: 100 is all its vendor serves at once, and past 100 requests queue (200 is twice that). Type 1 to 9999": "負荷はプラグインが報告するパーセントです。100 はベンダーが同時に処理できる上限、100 を超えるとリクエストが待ち行列に入ります（200 はその 2 倍）。1〜9999 を入力",
    "Type a whole number from 1 to 9999": "1〜9999 の整数を入力してください",
    "{n}% busy now, as its plugin says": "プラグインの報告では現在 {n}% の負荷",
    "Session terminal": "セッション用ターミナル",
