    "Every version": "すべてのバージョン",
    "Stable": "安定版",
    "Every version as soon as it is out": "新しいバージョンが出るたびに更新します",
    "One version a week, out for three days first, and urgent fixes at once. What's new lists every change since yours": "公開から 3 日経ったバージョンを週に 1 回、緊急の修正はすぐに届けます。新機能には今のバージョン以降のすべての変更がまとめて表示されます",
    "While automatic updates are on": "自動アップデートがオンのとき",
    "Restart automatically": "自動で再起動",
    "Download updates automatically": "アップデートを自動でダウンロード",
    "Off: a newer version is only shown, with its size; it downloads when you click Download update. For metered networks and proxies billed by traffic": "オフ：新しいバージョンはサイズとともに表示するだけで、「アップデートをダウンロード」をクリックしたときにダウンロードします。従量課金のネットワークやプロキシ向け",
    "Downloads a newer version as soon as it is found. Turn off on a metered network or a proxy billed by traffic": "新しいバージョンが見つかるとすぐにダウンロードします。従量課金のネットワークやプロキシではオフにできます",
    "Download update": "アップデートをダウンロード",
