    "Once an update is downloaded, restarts into it without cutting off an agent's request": "アップデートのダウンロード後、エージェントのリクエストを中断せずに再起動して適用します",
    "How often magpie looks for a newer version": "magpie が新しいバージョンを確認する頻度",
