    "restarts once the gateway is idle": "ゲートウェイがアイドルになったら再起動します",
    "restarts once the Claude subscription's replies have finished": "Claude サブスクリプションの応答が終わると再起動します",
    "magpie restarts to update to {v} once the replies through a Claude subscription have finished: {busy}. Other requests carry on across the restart. Click to restart now.": "Claude サブスクリプションの応答が終わると、magpie は再起動して {v} にアップデートします：{busy}。ほかのリクエストは再起動をまたいで続きます。クリックすると今すぐ再起動します。",
    "Restart now": "今すぐ再起動",
    "Waiting to update": "アップデート待ち",
    "magpie restarts to update to {v} once the agents' requests through the gateway have finished: {busy}. Click to restart now.": "ゲートウェイを通るエージェントのリクエストが終わると、magpie は再起動して {v} にアップデートします：{busy}。クリックすると今すぐ再起動します。",
    "the gateway stayed busy for an hour, so magpie didn't restart; it updates when you restart or quit it": "ゲートウェイが 1 時間ずっと使用中だったため、magpie は再起動しませんでした。再起動または終了したときにアップデートされます",
