    "{v}'s download broke off, a network problem. Click Check to try again, or download it from the release page": "{v} のダウンロードが途中で切れました（ネットワークの問題）。「確認」で再試行するか、リリースページからダウンロードしてください",
    "{v} didn't start on this computer: Windows' Smart App Control (or another app control policy) blocked the new version, which isn't signed. magpie stays on {cur}. Download it and run it yourself, or turn Smart App Control off and check again": "{v} はこのコンピューターで起動できませんでした：Windows の「スマート アプリ コントロール」（または別のアプリ制御ポリシー）が署名のない新しいバージョンをブロックしました。magpie は {cur} のままです。ダウンロードして自分で実行するか、スマート アプリ コントロールをオフにしてから再度確認してください",
    "{v} didn't start on this computer, so magpie stays on {cur}": "{v} はこのコンピューターで起動できなかったため、magpie は {cur} のままです",
