    "Click to open the download page.": "クリックするとダウンロードページを開きます。",
    "macOS is running magpie from a temporary copy, so it can't update itself; move magpie to Applications and open it from there.": "macOS が magpie を一時的なコピーから実行しているため、自動アップデートできません。magpie を「アプリケーション」フォルダに移動し、そこから開いてください。",
    "magpie is running from its disk image, so it can't update itself; drag it to Applications and open it from there.": "magpie がディスクイメージから実行されているため、自動アップデートできません。「アプリケーション」フォルダにドラッグし、そこから開いてください。",
    "magpie can't write to the folder it runs from ({dir}), so it can't update itself; move it to a folder you can write to and open it from there.": "magpie は実行中のフォルダ（{dir}）に書き込めないため、自動アップデートできません。書き込み可能なフォルダに移動し、そこから開いてください。",
    "{manager} installed magpie ({pkg}), so {manager} updates it, not magpie: {cmd}": "magpie は {manager} でインストールされている（{pkg}）ため、magpie ではなく {manager} がアップデートします：{cmd}",
    "{manager} installed magpie, so {manager} updates it, not magpie.": "magpie は {manager} でインストールされているため、magpie ではなく {manager} がアップデートします。",
    "magpie runs in a container, so it can't update itself; pull the new image (docker pull ghcr.io/yetone/magpie:latest) and recreate the container.": "magpie はコンテナで実行されているため、自動アップデートできません。新しいイメージを取得し（docker pull ghcr.io/yetone/magpie:latest）、コンテナを作り直してください。",
