    "Couldn't download {v} through the mirror {mirror}; it may be down or sent a file that doesn't match the release, which isn't installed": "ミラー {mirror} 経由で {v} をダウンロードできませんでした。ミラーが停止しているか、リリースと一致しないファイルが送られました（インストールされません）",
