    "Puts {dir} first in your user PATH and writes magpie.cmd there, which runs {name}": "{dir} をユーザーの PATH の先頭に置き、{name} を実行する magpie.cmd をそこに書きます",
    "Added: magpie.cmd beside {name} runs it as magpie; open a new PowerShell or Command Prompt window to run magpie": "追加しました：{name} の隣の magpie.cmd が magpie コマンドとしてそれを実行します。新しい PowerShell かコマンドプロンプトのウィンドウで magpie を実行できます",
    "which runs {name}": "{name} を実行します",
