    "Added: open a new terminal window to run magpie": "追加しました：新しいターミナルウィンドウで magpie を実行できます",
    "macOS runs magpie from a temporary copy until it is moved to Applications: move it there first": "アプリケーションに移すまで、macOS は magpie を一時コピーから実行します：先に移してください",
