    "macOS runs magpie from a temporary copy until it is moved to Applications: move it there, open it again, then add the command": "アプリケーションに移すまで、macOS は magpie を一時コピーから実行します：移して開き直してから、コマンドを追加してください",
    "magpie is running from its disk image: copy it to Applications, open it from there, then add the command": "magpie はディスクイメージから実行されています：アプリケーションにコピーしてそこから開き、コマンドを追加してください",
    "no folder on your PATH can take the magpie command: add ~/.local/bin to a shell's profile below": "PATH 上に magpie コマンドを置けるフォルダがありません：下でシェルの設定ファイルに ~/.local/bin を追加してください",
