    "about {amount} a day": "1 日あたり約 {amount}",
    "Solid: the balance as magpie read it. Dashed: a straight line fitted through it since the last top-up, carried on to where it runs out. Click to enlarge.": "実線：magpie が読み取った残高。破線：前回のチャージ以降を最小二乗法で当てはめた直線で、尽きるところまで延ばしたもの。クリックで拡大。",
    "Latest readings:": "最近の読み取り値：",
    "Solid: what was left. Dashed: an even pace, full at the cycle's start to empty at its reset; a line above its dashes lasts the cycle, one below runs out before the reset.": "実線：残量。破線：均等なペースで、サイクル開始時に満タン、リセット時に空になる線です。実線が破線より上ならサイクル終了まで持ち、下ならリセット前に使い切ります。",
    "Each window's line has the dash shown beside its name. Dotted: an even pace, full at the cycle's start to empty at its reset; a line above its dots lasts the cycle, one below runs out before the reset.": "各ウィンドウの線種は名前の横に表示されます。点線：均等なペースで、サイクル開始時に満タン、リセット時に空になる線です。線が点線より上ならサイクル終了まで持ち、下ならリセット前に使い切ります。",
