    "What was left over time, under each account's meters": "各アカウントのメーターの下に残量の推移を表示します",
    "{name}: {n} left, read {when}": "{name}：残り {n}、{when} に取得",
    "Now": "現在",
    "{name}: this cycle": "{name}：今回のサイクル",
    "{name}: what was left this cycle, against an even burn": "{name}：今回のサイクルの残量と均等な消費ペースの比較",
    "Counted from magpie's readings of the vendor's meter, since {date}: what is used while magpie isn't reading it is counted on the day it next does": "{date} 以降、magpie がベンダーのメーターを読み取った値から集計しています。magpie が読み取っていない間に使った分は、次に読み取った日に計上されます",
