    "This key is set to {api} only, but {name} has no {api} URL, so no request reaches {api} with it. Fill in the {api} URL, or set the key to Any protocol.": "このキーは {api} 専用ですが、{name} には {api} の URL がないため、このキーでのリクエストは {api} に届きません。{api} の URL を入力するか、キーを「任意のプロトコル」に戻してください。",
