    "Strict": "厳格",
    "A conversation stays with the account or key that answered it and never moves to another, even past its usage cap: when that one is rate limited or out of quota, the error goes to the agent. New conversations are routed as usual.": "会話は応答したアカウントまたはキーに留まり、使用量上限を超えても他へ移りません。そのアカウントがレート制限されるか割り当てを使い切ると、エラーはそのままエージェントに渡ります。新しい会話は通常どおりルーティングされます。",
    "Rate limited": "レート制限時",
