    "Agents never see them: a routing group picks one as its classifier.": "エージェントからは見えません。ルーティンググループが分類モデルとして 1 つを選びます。",
    "Jev's names · Fetch models asks the vendor": "Jev の名前 · 「モデルを取得」でベンダーに問い合わせます",
    "Jev endpoint": "Jev エンドポイント",
    "The address Jev is asked at; paste the one from your gateway's docs, e.g. Cloudflare's …/accounts/<account id>/ai/run": "Jev に問い合わせるアドレスです。ゲートウェイのドキュメントにあるものを貼り付けてください（例：Cloudflare の …/accounts/<account id>/ai/run）",
    "Routing groups name its models as {id} for their classifier": "ルーティンググループは分類モデルとしてそのモデルを {id} と指定します",
    "A decision API on System One (TypeSafe's Jev, a gateway's, or Bailian's decision model) — what a routing group asks as a turn begins": "System One 上の判定 API（TypeSafe の Jev、ゲートウェイのもの、または Bailian の判定モデル）— ターンの開始時にルーティンググループが問い合わせます",
    "a decision API's root, POST …/systemone under it: its models are a routing group's classifier, never an agent's": "判定 API のルート。その下の POST …/systemone を使います。モデルはルーティンググループの分類モデル専用で、エージェントには使われません",
    "System One endpoint": "System One エンドポイント",
    "Workspace ID": "ワークスペース ID",
    "Give the workspace ID your API key belongs to, or pick the Token Plan": "API キーが属するワークスペース ID を入力するか、Token Plan を選んでください",
    "e.g. ws-…, from the Bailian console": "例：ws-…（Bailian コンソールで確認）",
    "The workspace your API key belongs to, in the Bailian console; its decision model is asked at that workspace's host": "API キーが属する Bailian コンソールのワークスペースです。判定モデルにはそのワークスペースのホストで問い合わせます",
    "The address the decision model is asked at, POST …/systemone under it; the workspace ID above fills it in": "判定モデルに問い合わせるアドレスで、その下の POST …/systemone を使います。上のワークスペース ID を入れると自動入力されます",
    "The address its decision models are asked at, POST …/systemone under it": "このプロバイダーの判定モデルに問い合わせるアドレスで、その下の POST …/systemone を使います",
    "A decision API is asked with one model: type it and press Detect APIs": "判定 API には 1 つのモデルで問い合わせます。モデルを入力して「API を検出」を押してください",
    "Workspace · Beijing": "ワークスペース · 北京",
    "Workspace · Singapore": "ワークスペース · シンガポール",
    "Token Plan · Beijing": "Token Plan · 北京",
    "as the group's effort says": "グループの推論レベルに従う",
    "whatever the agent asks": "エージェントの指定にかかわらず",
