    "{model} is asked for OpenAI's fast mode for {agent}, where your provider serves it. Click to send it as {agent} asks": "{agent} の {model} で、プロバイダーに OpenAI の高速モードを求めています（対応していれば有効）。クリックすると {agent} の指定どおりに送ります",
    "Ask your provider for OpenAI's fast mode (service_tier \"priority\") on {model} for {agent}: quicker, at a higher price, where it serves it": "{agent} の {model} で、プロバイダーに OpenAI の高速モード（service_tier \"priority\"）を求める：対応していれば速く、料金は高め",
    "Routed": "ルーティング先",
