    "{n} accounts": "{n} 個のアカウント",
    "Show 1 more account": "さらに 1 個のアカウントを表示",
    "Show {n} more accounts": "さらに {n} 個のアカウントを表示",
    "Show fewer accounts": "アカウントの表示を減らす",
    "All {n} accounts": "全 {n} アカウント",
    "These accounts' windows together: amounts of one unit are added up; a window said only as a share is the mean of the accounts on one plan, which have the same allowance. Each account is below.": "これらのアカウントの枠の合計：同じ単位の量は足し合わせ、割合だけの枠は同じプランのアカウント（枠の大きさが同じ）の平均です。各アカウントは下にあります。",
    "The mean of {n} accounts on one plan": "同じプランの {n} アカウントの平均",
    "Unlimited on each of {n} accounts": "{n} アカウントすべて無制限",
    "Added up over {n} accounts": "{n} アカウントの合計",
    "{n} more read before it started again: left out": "ほかに {n} 件はリセット前の読み取りのため除外",
    "{n} of them can't spend theirs before a longer window used up starts again: counted as none left": "うち {n} 件は、より長い枠を使い切っており、そのリセットまで使えないため残りなしとして計上",
    "The first of them starts again {when}": "最も早いものは {when} にリセット",
    "{n} couldn't be read": "{n} 件は読み取れませんでした",
    "An account whose reading failed isn't counted as empty or full: it is left out of these figures": "読み取りに失敗したアカウントは空とも満杯とも数えず、これらの数字から除外します",
    "Show {n} more keys": "さらに {n} 個のキーを表示",
    "Show fewer keys": "キーの表示を減らす",
    "{sum} in all": "合計 {sum}",
    "The {n} keys' balances added up": "{n} 個のキーの残高の合計",
    "Show 1 more account in full": "さらに 1 個のアカウントを詳しく表示",
    "Show {n} more accounts in full": "さらに {n} 個のアカウントを詳しく表示",
    "Show the other accounts in brief": "他のアカウントを簡潔に表示",
    "Show all {n} accounts in full": "{n} 個すべてのアカウントを詳しく表示",
    "Show every account in brief": "すべてのアカウントを簡潔に表示",
    "Show this account in full": "このアカウントを詳しく表示",
    "Show this account in brief": "このアカウントを簡潔に表示",
    "A conversation stays with the account or key that answered it while what the vendor cached of it is worth keeping — within a turn always, across turns while it's fresh.": "会話は、ベンダーがキャッシュした内容に保持する価値がある間、応答したアカウントやキーにとどまります。ターン内では常に、ターンをまたぐ場合はキャッシュが新しい間です。",
    "A conversation stays with the account or key that answered it for the whole session, while it can answer.": "会話はセッション全体を通じて、応答できる限り、応答したアカウントやキーにとどまります。",
    "A conversation stays put within a turn, while the agent sends tool results back; when you speak again, routing decides afresh.": "ターン内（エージェントがツール結果を返している間）は移りません。次に発言したときに、ルーティングが改めて決めます。",
    "Every request is routed afresh, whoever answered its conversation before.": "各リクエストは、以前に誰が会話に応答したかにかかわらず、改めてルーティングされます。",
    "Mask the accounts on every page — email addresses and account names — for a screenshot to share": "スクリーンショットを共有できるよう、すべてのページのアカウント（メールアドレスとアカウント名）を伏せます",
    "Least used": "使用量が最少",
    "requests": "リクエスト",
    "request": "リクエスト",
    "rerouted": "再ルーティング",
    "WorkBuddy refuses chats from Codex and Claude Code (their system prompt); use it from Hermes, OpenCode or Pi, or add another provider to this group": "WorkBuddy は Codex と Claude Code からのチャットを（そのシステムプロンプトが原因で）拒否します。Hermes、OpenCode、Pi から使うか、このグループに別のプロバイダを追加してください",
    "Antigravity answers this 429 to the system prompt of Claude Code and the Claude Agent SDK (Claude Desktop's chats) whatever quota is left, so it is not a quota and waiting won't help; use another provider for these chats, or put one after Antigravity in a routing group": "Antigravity は Claude Code と Claude Agent SDK（Claude Desktop のチャット）のシステムプロンプトに対し、残りクォータに関係なくこの 429 を返します。クォータ切れではなく、待っても解決しません。これらのチャットには別のプロバイダを使うか、ルーティンググループで Antigravity の後に別のプロバイダを置いてください",
    "Antigravity answers this 429 to Codex's own system prompt for GPT-5 models whatever quota is left, so it is not a quota and waiting won't help; a Codex chat begun on a GPT model keeps that prompt after a model switch or a fork, so start a new chat on this model": "Antigravity は Codex の GPT-5 モデル向けシステムプロンプトに対し、残りクォータに関係なくこの 429 を返します。クォータ切れではなく、待っても解決しません。GPT モデルで始めた Codex のチャットは、モデルを切り替えたりフォークしたりしてもそのプロンプトを持ち続けるので、このモデルで新しいチャットを始めてください",
    "Antigravity answers this 429 to Hermes Agent's earlier default persona (its SOUL.md) whatever quota is left, so it is not a quota and waiting won't help; Hermes' current default persona goes through, so put it in SOUL.md, or use another provider for these chats": "Antigravity は Hermes Agent の以前のデフォルトのペルソナ（SOUL.md）に対し、残りクォータに関係なくこの 429 を返します。クォータ切れではなく、待っても解決しません。Hermes の現在のデフォルトのペルソナは通るので、それを SOUL.md に書くか、これらのチャットには別のプロバイダーを使ってください",
    "the provider's network firewall blocked requests from this IP; wait a while, or switch to another network or proxy": "プロバイダのネットワークファイアウォールがこの IP からのリクエストをブロックしました。しばらく待つか、別のネットワークやプロキシに切り替えてください",
    "ZCode's risk control blocked this account for unusual activity (code 3012); it rests, and the group's other providers are used. If the ZCode app fails on this account too, only ZCode support can lift the block": "ZCode のリスク管理が不審なアクティビティを理由にこのアカウントをブロックしました（コード 3012）。このアカウントは休止し、グループの他のプロバイダが使われます。ZCode アプリでもこのアカウントが失敗する場合、解除できるのは ZCode サポートだけです",
    "rate limited": "レート制限",
    "out of credit": "クレジット不足",
    "quota used up": "クォータ切れ",
    "failed": "失敗",
    "canceled": "キャンセル済み",
    "needs verification": "要認証",
    "refused (safety filter)": "拒否（安全フィルター）",
