    "The model a subagent starts on when Codex's lead names none; the lead may still name another. To hold every subagent to one model, set the subagent model": "Codex のリードがモデルを指定しないときにサブエージェントが使うモデルです。リードは別のモデルを指定することもできます。すべてのサブエージェントを 1 つのモデルに固定するには、サブエージェントのモデルを設定してください",
    "Claude Code's lead, or a subagent's own definition, may name a model or tier for it; a model set here is for the subagents that name none": "Claude Code のリードやサブエージェント自身の定義が、モデルや階層を指定できます。ここで設定したモデルは、指定のないサブエージェントに使われます",
