    "A reply that reasoned counts only its answer, from its first text: the reasoning was written before the stream showed it": "推論した応答は、最初の本文からの回答部分のみ数えます。推論はストリームに出る前に書き終わっています",
    "No answer text: speed includes reasoning only when visible reasoning streamed; hidden reasoning has no speed": "本文がない場合、継続的にストリームされた可視の推論のみ速度に含めます。非表示の推論には速度を表示しません",
