    "Measured on {k} reply, from its first token to its end; the others tell no speed": "{k} 件の応答で実測：最初のトークンから終わりまで。ほかのリクエストは速度を計れません",
    "Measured on {k} reply, from its first token to its end": "{k} 件の応答で実測：最初のトークンから終わりまで",
    "Measured on {k} replies, from their first token to their end; the others tell no speed": "{k} 件の応答で実測：最初のトークンから終わりまで。ほかのリクエストは速度を計れません",
    "Measured on {k} replies, from their first token to their end": "{k} 件の応答で実測：最初のトークンから終わりまで",
    "At least: {k} reply read from a session file, which doesn't say when its answer began, so time before that is counted too": "下限：セッションファイルから読んだ {k} 件の応答。回答が始まった時刻がないため、その前の時間も含まれます",
    "At least: {k} replies read from session files, which don't say when their answers began, so time before that is counted too": "下限：セッションファイルから読んだ {k} 件の応答。回答が始まった時刻がないため、その前の時間も含まれます",
