    "{agent} needs an administrator here, and the administrator prompt was declined.": "{agent} にはここで管理者権限が必要ですが、管理者の確認が拒否されました。",
    "{agent} needs an administrator here, and magpie couldn't ask Windows for one ({why}).": "{agent} にはここで管理者権限が必要ですが、magpie は Windows に管理者権限を求められませんでした（{why}）。",
    "Try again and allow it, or run {cmd} in a terminal opened as administrator.": "もう一度試して許可するか、管理者として開いたターミナルで {cmd} を実行してください。",
