    "Serve the vendor's list, up to {n} of it (dashed), models it lists later too": "ベンダーのリストを最大 {n} 件（破線）提供します。後から追加されたモデルも含みます",
    "Serve only the models picked": "選択したモデルだけを提供します",
    "Usage only": "使用量のみ",
    "Best in family": "系列の最新のみ",
    "Best in family: agents see the newest model of each family it lists (dashed), up to {n}. A newer one it lists later takes the old one's place.": "系列の最新のみ：エージェントには一覧の各系列の最新モデルが見えます（破線、最大 {n} 個）。後で新しいモデルが載ると、古いものと自動で入れ替わります。",
    "Route nothing to it: no agent or routing group uses its models, and those it lists later aren't added. Its balance and usage still show.": "何もルーティングしません。エージェントもルーティンググループもモデルを使わず、後から追加されたモデルも加わりません。残高と使用量は引き続き表示されます。",
    "usage only": "使用量のみ",
    "Vendor's list: agents don't see it, the routing groups its models are in use up to {n} of it (dashed). Click a model to pick just it.": "ベンダーのリスト：エージェントには表示されず、モデルが属するルーティンググループが最大 {n} 件（破線）を使います。モデルをクリックするとそれだけを選択します。",
    "Vendor's list: agents see up to {n} of its models (dashed), and those it lists later. Click a model to pick just it.": "ベンダーのリスト：エージェントにはモデルが最大 {n} 件（破線）表示され、後から追加されたものも表示されます。モデルをクリックするとそれだけを選択します。",
    "Free only": "無料のみ",
    "Pick only the free models (those the filter shows), unpicking the others": "無料モデル（フィルタで表示されているもの）だけを選択し、他は選択を解除します",
