    "Unpicked {n} models that didn't answer": "応答しなかったモデル {n} 個の選択を外しました",
    "Unpick the models whose last test failed; those that answered, and those not tested, stay picked": "前回のテストに失敗したモデルの選択を外します。応答したモデルと未テストのモデルは選択されたままです",
    "Every picked model that was tested answered": "テストした選択中のモデルはすべて応答しました",
