    "Uninstall…": "アンインストール…",
    "Uninstall magpie": "magpie をアンインストール",
    "Disconnects every agent, putting back what each had, then removes magpie's service and files": "すべてのエージェントの接続を解除して元の設定に戻し、magpie のサービスとファイルを削除します",
    "Uninstall magpie?": "magpie をアンインストールしますか？",
    "Every agent is disconnected and gets back what it had before magpie; what you changed by hand since stays. magpie's background service, opening at login and shortcuts are removed, and once it quits, its providers, keys, settings and usage are deleted. The app itself stays where it is: delete it to finish.": "すべてのエージェントの接続を解除し、magpie を使う前の設定に戻します。その後に手で変更した箇所はそのまま残ります。magpie のバックグラウンドサービス、ログイン時の起動、ショートカットを削除し、magpie の終了後にプロバイダ、キー、設定、使用量を削除します。アプリ本体は元の場所に残るので、削除すれば完了です。",
    "Uninstall": "アンインストール",
    "Some of magpie couldn't be taken off": "magpie の一部を削除できませんでした",
    "Nothing else was removed, and magpie keeps running. What is left: {left}": "ほかには何も削除しておらず、magpie は動作を続けます。残っているもの：{left}",
    "Open the Codex app again": "Codex アプリを開き直してください",
    "The Codex app is still on the settings it read before: quit it and open it again. magpie quits now, and its files are deleted once it has.": "Codex アプリは以前に読み込んだ設定のままです。終了してから開き直してください。magpie は今から終了し、終了後にファイルを削除します。",
    "Quit magpie": "magpie を終了",
