    "Go to the MCP servers you can add, under the list": "リストの下にある追加できる MCP サーバーへ移動",
    "Go to the skills you can add, under the list": "リストの下にある追加できるスキルへ移動",
    "Search MCP servers — GitHub, Postgres, Figma…": "MCP サーバーを検索 — GitHub、Postgres、Figma…",
    "Search skills on skills.sh — react, pdf, testing…": "skills.sh でスキルを検索 — react、pdf、testing…",
    "Remote": "リモート",
    "Local": "ローカル",
