    "(optional)": "（任意）",
    "Official": "公式",
    "From": "提供元",
    "Up-to-date documentation and code examples for any library, straight into the prompt.": "あらゆるライブラリの最新ドキュメントとコード例を、そのままプロンプトに。",
    "Drive a real browser: open pages, click, type and read them through the accessibility tree.": "実際のブラウザを操作：ページを開き、クリック・入力し、アクセシビリティツリーで読み取ります。",
    "Control and inspect a live Chrome: console, network, performance traces and screenshots.": "起動中の Chrome を制御・検査：コンソール、ネットワーク、パフォーマンストレース、スクリーンショット。",
    "Repositories, issues, pull requests, Actions and code search on GitHub.": "GitHub のリポジトリ、Issue、プルリクエスト、Actions、コード検索。",
    "Ask questions about any public GitHub repository and read its generated wiki.": "公開されている GitHub リポジトリについて質問し、生成された Wiki を読めます。",
    "Web search and code search built for agents, with clean page contents.": "エージェント向けのウェブ検索とコード検索。ページ内容をきれいに返します。",
    "Real-time web search, vertical searches (finance, papers, code, security and more) and full pages as Markdown.": "リアルタイムのウェブ検索、分野別検索（金融、論文、コード、セキュリティなど）、ページ全体の Markdown 化。",
    "Read, write and search files, limited to the folders you allow.": "許可したフォルダに限って、ファイルの読み書きと検索を行います。",
    "Fetch a web page and hand it over as Markdown.": "ウェブページを取得して Markdown で渡します。",
    "A knowledge graph the agent keeps across conversations.": "エージェントが会話をまたいで保持するナレッジグラフ。",
    "Think a problem through step by step, revising and branching as it goes.": "修正や分岐をしながら、問題を一歩ずつ考え抜きます。",
    "Read, search and change Git repositories.": "Git リポジトリの読み取り、検索、変更。",
    "The current time anywhere, and conversions between time zones.": "任意の場所の現在時刻と、タイムゾーン間の変換。",
    "Issues, errors and traces from Sentry, and Seer's analysis of them.": "Sentry の Issue、エラー、トレースと、それらに対する Seer の分析。",
    "Find, create and update Linear issues, projects and comments.": "Linear の Issue、プロジェクト、コメントを検索・作成・更新。",
    "Search, read and write pages and databases in your Notion workspace.": "Notion ワークスペースのページとデータベースを検索・閲覧・編集。",
    "Jira issues and Confluence pages from Atlassian Cloud.": "Atlassian Cloud の Jira Issue と Confluence ページ。",
    "Manage Supabase projects: tables, SQL, migrations, logs and edge functions.": "Supabase プロジェクトを管理：テーブル、SQL、マイグレーション、ログ、Edge Functions。",
    "Customers, payments, subscriptions and Stripe's documentation.": "顧客、支払い、サブスクリプション、そして Stripe のドキュメント。",
    "Projects, deployments and logs on Vercel, and its documentation.": "Vercel のプロジェクト、デプロイ、ログと、そのドキュメント。",
    "Serverless Postgres on Neon: projects, branches and SQL.": "Neon のサーバーレス Postgres：プロジェクト、ブランチ、SQL。",
    "Search Cloudflare's documentation.": "Cloudflare のドキュメントを検索。",
    "Official Microsoft and Azure documentation and code samples.": "Microsoft と Azure の公式ドキュメントとコードサンプル。",
    "Search models, datasets, Spaces and papers on the Hugging Face Hub.": "Hugging Face Hub のモデル、データセット、Spaces、論文を検索。",
    "Web, news, image and local search from Brave's independent index.": "Brave の独自インデックスによるウェブ、ニュース、画像、ローカル検索。",
    "Scrape, crawl and search the web into clean Markdown.": "ウェブをスクレイピング・クロール・検索し、きれいな Markdown に。",
    "Search and extract from the web with Tavily.": "Tavily でウェブを検索・抽出。",
    "Personal access token": "個人アクセストークン",
    "Folder": "フォルダ",
    "The folder it may read and write": "読み書きを許可するフォルダ",
    "Optional — raises the rate limit. From context7.com/dashboard": "任意 — レート制限が上がります。context7.com/dashboard で取得",
    "Optional — raises the rate limit. From anysearch.com/console/api-keys": "任意 — レート制限が上がります。anysearch.com/console/api-keys で取得",
    "{name} is installed — sign in to use it": "{name} をインストールしました — サインインして使ってください",
    "{name} is installed": "{name} をインストールしました",
    "Replace {old} with {new}?": "{old} を {new} に置き換えますか？",
    "{new} and {old} are both the package {package}, and only one of them can be installed: {old} is removed, and its options and sign-ins pass to {new}.": "{new} と {old} はどちらも {package} というパッケージで、インストールできるのは一方だけです。{old} は削除され、そのオプションとサインインは {new} に引き継がれます。",
    "{new} and {old} are both the package {package}, and only one of them can be installed: {old} is removed, and its options and sign-ins pass to {new}. {old} is off, so {new} is installed off too.": "{new} と {old} はどちらも {package} というパッケージで、インストールできるのは一方だけです。{old} は削除され、そのオプションとサインインは {new} に引き継がれます。{old} はオフなので、{new} もオフのままインストールされます。",
    "Getting Bun…": "Bun を取得中…",
    "Plugins run on Bun {v}, downloaded once": "プラグインは Bun {v} で動作します（ダウンロードは一度だけ）",
    "Bun, which runs plugins, can't start on this version of Windows: it needs Windows 10 version 1809 or later, or Windows Server 2019 or later. Update Windows to use plugins, or set MAGPIE_BUN to a bun that runs here.": "プラグインを動かす Bun は、このバージョンの Windows では起動できません。Windows 10 バージョン 1809 以降、または Windows Server 2019 以降が必要です。プラグインを使うには Windows を更新するか、MAGPIE_BUN にここで動く bun を指定してください。",
    "Bun, which runs plugins, can't start on this computer's processor: it needs an x64 processor with SSE4.2 (Intel or AMD from 2008 on; in a virtual machine, a CPU type that passes it through). Run magpie on such a processor to use plugins, or set MAGPIE_BUN to a bun that runs here.": "プラグインを動かす Bun は、このコンピューターのプロセッサでは起動できません。SSE4.2 に対応した x64 プロセッサ（2008 年以降の Intel または AMD。仮想マシンでは SSE4.2 を引き渡す CPU タイプ）が必要です。プラグインを使うにはそのようなプロセッサで magpie を実行するか、MAGPIE_BUN にここで動く bun を指定してください。",
    "Coming soon": "近日公開",
    "{n} stars on GitHub": "GitHub のスター {n}",
    "Unofficial, on GitHub": "非公式 · GitHub",
    "GitHub refused this token: it may have expired or been revoked. Requests go without one (60 an hour) until it is replaced.": "GitHub がこのトークンを拒否しました。期限切れか取り消された可能性があります。差し替えるまで、リクエストはトークンなし（1 時間 60 回）で送られます。",
    "Looking on GitHub": "GitHub を検索中",
