    "repositories their authors tagged {topic} — nobody has reviewed them; read the code before you install one": "作者自身が {topic} タグを付けたリポジトリ。レビューされていないので、インストール前にコードを確認してください",
    "Stars": "スター",
    "Unofficial: {owner} tagged it {topic} on GitHub, and nobody at magpie has reviewed it. It is installed from the repository as it stands, and runs with your sign-in or your requests.": "非公式：{owner} が GitHub で {topic} タグを付けたもので、magpie はレビューしていません。リポジトリの現在のコードがインストールされ、あなたのサインインやリクエストを扱います。",
    "Unofficial: {owner} tagged it {topic} on GitHub, and nobody at magpie has reviewed it. It is installed from npm, as its author published it from the repository, and runs with your sign-in or your requests.": "非公式：{owner} が GitHub で {topic} タグを付けたもので、magpie はレビューしていません。作者がこのリポジトリから npm に公開したものがインストールされ、あなたのサインインやリクエストを扱います。",
