    "magpie's own sign-in to this subscription is deprecated: this plugin takes its place, and accounts signed in there move to it.": "magpie 内蔵のこのサブスクリプションへのサインインは非推奨です。このプラグインが引き継ぎ、内蔵版でサインインしたアカウントはプラグインに移ります。",
