    "Download the plugin list, plugins and Bun from mirrors in China first (npmmirror, jsDelivr), their official addresses after. Each is a copy of the very file, checked as the original is": "プラグインリスト、プラグイン、Bun をまず中国のミラー（npmmirror、jsDelivr）から、次に公式のアドレスからダウンロードします。ミラーのものは同じファイルのコピーで、オリジナルと同じように検証されます",
    "Search plugins": "プラグインを検索",
