    "Add a window": "時間帯を追加",
    "Inside a window a call costs the official price times its rate, on top of the price rate; outside every window the price rate alone counts. The first window that holds a call wins. Times are on the clock of the computer magpie runs on, and 22:00–6:00 crosses midnight. No day ticked is every day. A price you set for a model is scaled by the window too. Changing the windows prices the calls already counted again, as a changed price rate does.": "時間帯内の呼び出しは公式価格にその時間帯の倍率を掛けた額で計上され、価格倍率にさらに重ねられます。時間帯の外では価格倍率のみが適用されます。呼び出しは最初に一致した時間帯の倍率です。時刻は magpie が動いているコンピュータの時計で、22:00–6:00 は深夜0時をまたぎます。曜日を1つも選ばない場合は毎日です。モデルに個別に設定した価格も同様にその倍率が掛かります。時間帯を変更すると、記録済みの呼び出しも新しい時間帯で計算し直されます(価格倍率の変更と同じです)。",
    "DeepSeek's own API, Command Code, OpenCode Go and Ollama Cloud already count their DeepSeek models' peak hours at double: don't add those hours as a window, or they count twice.": "DeepSeek 公式 API、Command Code、OpenCode Go、Ollama Cloud の DeepSeek モデルは、それぞれのピーク時間帯をすでに 2 倍で計上しています。その時間帯を時間帯倍率として追加しないでください。二重に計上されます。",
